export function createAudio(onSpeaking){
const $=id=>document.getElementById(id),synth=window.speechSynthesis;let ctx,master,timer,enabled=false,step=0,next=0,active=null,pending=[],watchdog,voices=[],fileAudio=null,fileURL;
const status=text=>$('audio-status').textContent=text;
function voiceList(){const previous=$('voice-select').value;voices=synth?.getVoices().filter(v=>/^pt/i.test(v.lang))||[];$('voice-select').replaceChildren(new Option('Automática · português do Brasil',''));for(const v of voices)$('voice-select').add(new Option(v.name,v.voiceURI));if(voices.some(v=>v.voiceURI===previous))$('voice-select').value=previous}
voiceList();synth?.addEventListener('voiceschanged',voiceList);
function volume(){const gain=enabled&&$('music').checked?Number($('music-volume').value)/100*(active?.2:1):0;if(master&&ctx)master.gain.setTargetAtTime(fileAudio?0:gain,ctx.currentTime,.15);if(fileAudio)fileAudio.volume=gain}
function tone(midi,time,duration,gain,type='triangle'){const o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.value=440*2**((midi-69)/12);g.gain.setValueAtTime(0,time);g.gain.linearRampToValueAtTime(gain,time+.018);g.gain.exponentialRampToValueAtTime(.0001,time+duration);o.connect(g);g.connect(master);o.start(time);o.stop(time+duration+.02);o.onended=()=>{o.disconnect();g.disconnect()}}
// Original melody, no Dragon Ball composition or recording.
const phrases=[[76,79,83,86,83,79,81,78],[74,78,81,85,81,78,76,74],[72,76,79,84,83,79,76,79],[74,78,81,86,85,81,78,74]];
function schedule(){if(!enabled||!ctx||ctx.state!=='running')return;if(next<ctx.currentTime)next=ctx.currentTime+.03;while(next<ctx.currentTime+.18){const p=Math.floor(step/8)%4,b=step%8;if($('music').checked&&!fileAudio){tone(phrases[p][b],next,.28,.10,'triangle');if(b%2===0){tone([40,38,36,38][p],next,.3,.17);tone(48,next,.055,.16,'sine')}if(b===0){tone([64,62,60,62][p],next,.8,.035,'sawtooth');tone([71,69,67,69][p],next,.8,.03,'sawtooth')}}next+=60/124/2;step++}}
function pump(){if(!enabled||active||!pending.length)return;if(!$('voice').checked){pending=[];return}if(!synth){pending=[];return}const text=pending.shift(),u=new SpeechSynthesisUtterance(text);u.lang='pt-BR';u.rate=1.06;u.pitch=1.02;u.voice=voices.find(v=>v.voiceURI===$('voice-select').value)||voices.find(v=>v.lang==='pt-BR')||null;active=u;onSpeaking(true);volume();let done=false;const finish=()=>{if(done)return;done=true;clearTimeout(watchdog);active=null;onSpeaking(false);volume();pump()};u.onend=finish;u.onerror=finish;watchdog=setTimeout(()=>{synth.cancel();finish()},Math.max(12000,text.length*150));synth.speak(u)}
function clear(){pending=[];clearTimeout(watchdog);if(active)synth?.cancel();active=null;onSpeaking(false);volume()}
async function start(){try{if(!ctx){ctx=new(window.AudioContext||window.webkitAudioContext)();master=ctx.createGain();master.connect(ctx.destination)}await ctx.resume();enabled=true;next=ctx.currentTime+.04;clearInterval(timer);timer=setInterval(schedule,80);volume();if(fileAudio&&$('music').checked)await fileAudio.play();$('audio-start').textContent='■ Desligar som';status(synth?'Som ativado · voz em português e música.':'Música ativada. Este navegador não oferece síntese de voz.');pump()}catch{status('Não foi possível ativar o áudio. Toque novamente em Ativar som.')}}
function stop(){enabled=false;clear();clearInterval(timer);fileAudio?.pause();volume();ctx?.suspend();$('audio-start').textContent='♫ Ativar som e voz';status('Som desligado.')}
$('audio-start').onclick=()=>enabled?stop():start();$('music-volume').oninput=volume;$('music').onchange=()=>{volume();if(fileAudio){if(enabled&&$('music').checked)fileAudio.play().catch(()=>status('Toque em Ativar som para iniciar a música.'));else fileAudio.pause()}};$('voice').onchange=()=>{if(!$('voice').checked)clear()};
$('custom-music').onchange=async e=>{const file=e.target.files[0];if(!file)return;fileAudio?.pause();if(fileURL)URL.revokeObjectURL(fileURL);fileURL=URL.createObjectURL(file);fileAudio=new Audio(fileURL);fileAudio.loop=true;fileAudio.onerror=()=>status('Esse arquivo de áudio não pôde ser reproduzido.');volume();if(enabled&&$('music').checked)try{await fileAudio.play()}catch{status('Toque em Ativar som para reproduzir o arquivo.')}};
$('original-music').onclick=()=>{fileAudio?.pause();fileAudio=null;if(fileURL)URL.revokeObjectURL(fileURL);fileURL=null;$('custom-music').value='';volume();status(enabled?'Trilha original ativada.':'Ative o som para ouvir a trilha original.')};
return {say(text){if(!enabled||!$('voice').checked||!text)return;if(pending.length>=40)pending.shift();pending.push(text);pump()},clear,stop,burst(){if(!enabled||!ctx)return;for(let i=0;i<6;i++)tone(48+i*7,ctx.currentTime+i*.045,.22,.2,'sine')}};
}
